// MineBench: "a choo-choo train"
// Steam locomotive (black boiler, red cab, brass dome, flared stack, cowcatcher),
// coal tender and two green coaches on rails, down a river valley with hills,
// a water tower, a station house, trees, lamp posts and a plume of smoke.
// Train runs along X (front = +X). Centreline z = 128. Rails at z = 125 and z = 130.
// Block i spans [i, i+1); cc(i) is its centre.

const M = {
  boiler: 'black_wool', cab: 'red_wool', roof: 'black_wool', trim: 'gold_block',
  iron: 'iron_block', wood: 'oak_planks', glass: 'glass', glow: 'glowstone',
  coach: 'green_wool', stripe: 'yellow_wool', seat: 'red_wool', tender: 'gray_wool',
  tire: 'black_wool', spoke: 'red_wool', hub: 'gold_block', dirt: 'dirt', grass: 'grass_block',
  stone: 'stone', sand: 'sand', water: 'water', brick: 'bricks', slate: 'stone_bricks',
  log: 'oak_log', leaves: 'oak_leaves', ballast: 'cobblestone', tie: 'oak_planks',
  smoke: 'white_wool', smoke2: 'gray_wool', coal: 'black_wool'
};

function put(x, y, z, t) {
  x = Math.round(x); y = Math.round(y); z = Math.round(z);
  if (x < 0 || y < 0 || z < 0 || x > 255 || y > 255 || z > 255) return;
  block(x, y, z, t);
}
const cc = (i) => i + 0.5; // centre of block i

// Ragged ball. keep < 1 speckles it (leaves, smoke).
function blob(cx, cy, cz, r, t, rough, keep) {
  const R = Math.ceil(r) + 1;
  for (let x = Math.floor(cx) - R; x <= Math.floor(cx) + R; x++)
  for (let y = Math.floor(cy) - R; y <= Math.floor(cy) + R; y++)
  for (let z = Math.floor(cz) - R; z <= Math.floor(cz) + R; z++) {
    const d = Math.hypot(cc(x) - cx, cc(y) - cy, cc(z) - cz);
    if (d > r * (1 + rough * (rng() - 0.5))) continue;
    if (keep !== undefined && rng() > keep) continue;
    put(x, y, z, t);
  }
}

// Cylinder lying along X: axis at (y=yc, z=zc), blocks x0..x1.
// taper > 0 rounds the last `taper` blocks into the smokebox front.
function tubeX(x0, x1, yc, zc, r, t, taper) {
  for (let x = x0; x <= x1; x++) {
    let rr = r;
    if (taper && x > x1 - taper) {
      const k = (x - (x1 - taper)) / taper;
      rr = r * Math.sqrt(Math.max(0.64, 1 - k * k));
    }
    for (let y = Math.floor(yc - r) - 1; y <= Math.ceil(yc + r); y++)
    for (let z = Math.floor(zc - r) - 1; z <= Math.ceil(zc + r); z++)
      if (Math.hypot(cc(y) - yc, cc(z) - zc) <= rr) put(x, y, z, t);
  }
}

// Vertical cylinder: centre (xc, zc), blocks y0..y1. rin > 0 makes a hollow ring.
function tubeY(xc, zc, y0, y1, r, t, rin) {
  for (let y = y0; y <= y1; y++)
  for (let x = Math.floor(xc - r) - 1; x <= Math.ceil(xc + r); x++)
  for (let z = Math.floor(zc - r) - 1; z <= Math.ceil(zc + r); z++) {
    const d = Math.hypot(cc(x) - xc, cc(z) - zc);
    if (d <= r && d > (rin || 0)) put(x, y, z, t);
  }
}

// Wheel: a disc in the XY plane (the axle runs across the track, along Z).
// Black tyre, iron rim band, six red spokes, gold hub, open between spokes.
function wheel(xc, yc, R, z1, z2) {
  for (let x = Math.floor(xc - R) - 1; x <= Math.ceil(xc + R); x++)
  for (let y = Math.floor(yc - R) - 1; y <= Math.ceil(yc + R); y++) {
    const dx = cc(x) - xc, dy = cc(y) - yc, d = Math.hypot(dx, dy);
    if (d > R) continue;
    let t = null;
    if (d > R - 1.2) t = M.tire;
    else if (d > R - 2.4) t = M.iron;
    else if (d < 1.3) t = M.hub;
    else if (Math.abs(Math.sin(3 * Math.atan2(dy, dx))) * d / 3 < 0.55) t = M.spoke;
    if (t) for (let z = z1; z <= z2; z++) put(x, y, z, t);
  }
}

// ---- Landscape ---------------------------------------------------------------
const riverZ = (x) => 84 + 5 * Math.sin(x * 0.03);

// Extra ground height above y=0 at column (x, z): hills rise toward the far edge.
function hillTop(x, z) {
  const back = Math.max(0, (96 - z) / 96);
  const roll = 0.7 + 0.3 * Math.sin(x * 0.045 + 1.7) * Math.cos(z * 0.07);
  return Math.round(18 * Math.pow(back, 1.3) * roll);
}

function terrain() {
  for (let x = 0; x <= 255; x++)
  for (let z = 0; z <= 255; z++) {
    const river = Math.abs(z - riverZ(x));
    let top = hillTop(x, z), cap = M.grass;
    if (river < 3) { top = 0; cap = M.water; }      // river channel
    else if (river < 5) { top = 0; cap = M.sand; }  // sandy banks
    for (let y = 0; y <= top; y++)
      put(x, y, z, y === top ? cap : (y >= top - 3 ? M.dirt : M.stone));
  }
}

// Flowers scattered on the flat grass, kept off the track, station and river.
function flowers() {
  const kinds = [M.smoke, 'red_wool', 'yellow_wool', 'purple_wool'];
  for (let x = 0; x <= 255; x++)
  for (let z = 0; z <= 255; z++) {
    if (hillTop(x, z) > 0 || Math.abs(z - riverZ(x)) < 6) continue;
    if (z >= 116 && z <= 138) continue;
    if (x >= 196 && z <= 120) continue;
    if (rng() < 0.004) put(x, 1, z, kinds[Math.floor(rng() * kinds.length)]);
  }
}

// Ballast bed, sleepers and two iron rails along the whole valley.
function track() {
  box(0, 1, 121, 255, 1, 134, M.ballast);
  for (let x = 0; x <= 255; x += 2) box(x, 2, 122, x, 2, 133, M.tie);
  line(0, 3, 125, 255, 3, 125, M.iron);
  line(0, 3, 130, 255, 3, 130, M.iron);
}

// Station house behind the track: brick walls, slate roof, windows, door, gold sign.
function station() {
  const x0 = 200, x1 = 238, z0 = 106, z1 = 118;
  for (let x = x0; x <= x1; x++)
  for (let z = z0; z <= z1; z++) {
    const edge = x === x0 || x === x1 || z === z0 || z === z1;
    if (edge) {
      for (let y = 1; y <= 6; y++) {
        let t = M.brick;
        if ((z === z0 || z === z1) && y >= 3 && y <= 4 && (x - x0) % 4 !== 0) t = M.glass;
        if (z === z0 && x >= 218 && x <= 219 && y <= 3) t = M.wood;
        put(x, y, z, t);
      }
    }
    const pitch = Math.min(z - z0, z1 - z); // 0 at the eaves, 6 at the ridge
    for (let y = 7; y <= 7 + pitch; y++) put(x, y, z, M.slate);
  }
  for (const x of [204, 232]) line(x, 1, 105, x, 5, 105, M.iron);
  box(204, 6, 105, 232, 6, 105, M.trim);
}

// Water tower: four oak legs, iron-banded tank with water inside, domed cap.
function waterTower() {
  const cx = 92, cz = 108;
  for (const [lx, lz] of [[89, 105], [94, 105], [89, 110], [94, 110]]) line(lx, 1, lz, lx, 14, lz, M.log);
  for (let y = 15; y <= 20; y++)
  for (let x = cx - 5; x <= cx + 4; x++)
  for (let z = cz - 5; z <= cz + 4; z++) {
    const d = Math.hypot(cc(x) - cx, cc(z) - cz);
    if (d > 4) continue;
    let t = d > 3 ? M.wood : M.water;
    if (y === 15 || y === 20) t = M.iron;
    put(x, y, z, t);
  }
  tubeY(cx, cz, 21, 21, 3.6, M.iron);
  tubeY(cx, cz, 22, 22, 2.4, M.iron);
  put(cx, 23, cz, M.trim);
}

// Lamp posts with glowstone heads, both sides of the track.
function lamps() {
  for (const x of [6, 30, 54, 78, 102, 126, 150, 174, 198, 222, 246])
  for (const z of [120, 136]) {
    line(x, 1, z, x, 9, z, M.iron);
    put(x, 10, z, M.glow);
  }
}

// Trees on the flat ground and up the hills, kept clear of track, river, tower, station.
function trees() {
  let placed = 0;
  for (let tries = 0; placed < 26 && tries < 4000; tries++) {
    const x = 4 + Math.floor(rng() * 248), z = Math.floor(rng() * 256);
    if (z > 112 && z < 142) continue;
    if (Math.abs(z - riverZ(x)) < 7) continue;
    if (Math.abs(x - 92) < 9 && Math.abs(z - 108) < 9) continue;
    if (x > 196 && z < 122) continue;
    const base = hillTop(x, z) + 1;
    const h = 5 + Math.floor(rng() * 3);
    for (let y = base; y < base + h; y++) put(x, y, z, M.log);
    blob(x + 0.5, base + h, z + 0.5, 2.8 + rng() * 1.2, M.leaves, 0.3, 0.9);
    blob(x + 0.5 + (rng() - 0.5) * 2, base + h - 1.5, z + 0.5, 2.0 + rng(), M.leaves, 0.3, 0.9);
    placed++;
  }
}

// ---- Train -------------------------------------------------------------------

// Passenger coach: green body, yellow waist stripe, glass windows, black arched roof.
function coach(lo, hi) {
  box(lo, 12, 123, hi, 12, 132, M.wood);                       // floor
  for (let x = lo; x <= hi; x++) {
    const i = x - lo;
    const endCar = x === lo || x === hi;
    for (let y = 12; y <= 21; y++) {
      for (let z = 123; z <= 132; z++) {                         // end walls
        if (endCar) put(x, y, z, (y >= 15 && y <= 19 && z >= 126 && z <= 129) ? M.glass : M.coach);
      }
      for (const z of [122, 133]) {                              // long sides
        let t = y === 14 ? M.stripe : M.coach;
        if (y >= 15 && y <= 19 && i % 4 !== 0) t = M.glass;
        put(x, y, z, t);
      }
    }
    for (let y = 22; y <= 27; y++)                               // arched roof
      for (let z = 122; z <= 133; z++)
        if (Math.hypot(cc(y) - 22, cc(z) - 128) <= 6) put(x, y, z, M.roof);
    if (i % 6 === 3) put(x, 21, 128, M.glow);                    // ceiling lights
  }
  box(lo + 1, 13, 123, hi - 1, 13, 125, M.seat);                 // benches either side of the aisle
  box(lo + 1, 14, 123, hi - 1, 15, 123, M.seat);
  box(lo + 1, 13, 130, hi - 1, 13, 132, M.seat);
  box(lo + 1, 14, 132, hi - 1, 15, 132, M.seat);
  wheel(lo + 5, 8, 4, 124, 125); wheel(lo + 5, 8, 4, 130, 131);
  wheel(hi - 5, 8, 4, 124, 125); wheel(hi - 5, 8, 4, 130, 131);
  line(lo + 5, 8, 124, lo + 5, 8, 131, M.iron);
  line(hi - 5, 8, 124, hi - 5, 8, 131, M.iron);
}

// Coal tender: grey tank with gold stripes and a heaped load of coal.
function tender() {
  box(117, 12, 123, 140, 19, 132, M.tender);
  box(117, 15, 122, 140, 15, 122, M.trim);
  box(117, 15, 133, 140, 15, 133, M.trim);
  for (let x = 117; x <= 140; x++)
  for (let z = 123; z <= 132; z++) {
    const d = Math.hypot(x + 0.5 - 128.5, (z + 0.5 - 127.5) * 1.6);
    if (d < 13) put(x, 20, z, M.coal);
    if (d < 9 && rng() < 0.6) put(x, 21, z, M.coal);
    if (d < 5 && rng() < 0.4) put(x, 22, z, M.coal);
  }
  wheel(122, 8, 4, 124, 125); wheel(122, 8, 4, 130, 131);
  wheel(136, 8, 4, 124, 125); wheel(136, 8, 4, 130, 131);
  line(122, 8, 124, 122, 8, 131, M.iron);
  line(136, 8, 124, 136, 8, 131, M.iron);
}

// Steam locomotive: cab, boiler, dome, stack, headlamp, cowcatcher, running gear.
function loco() {
  box(144, 10, 122, 196, 11, 133, M.iron);                       // frame
  wheel(148, 8, 4, 124, 125); wheel(148, 8, 4, 130, 131);        // trailing wheels
  line(148, 8, 124, 148, 8, 131, M.iron);
  for (const xc of [158, 170, 182]) {                            // driving wheels
    wheel(xc, 10, 6, 124, 125); wheel(xc, 10, 6, 130, 131);
    line(xc, 10, 124, xc, 10, 131, M.iron);
  }
  line(158, 9, 122, 182, 9, 122, M.iron);                        // side rods
  line(158, 9, 133, 182, 9, 133, M.iron);
  box(186, 9, 119, 196, 15, 121, M.iron);                        // cylinders
  box(186, 9, 134, 196, 15, 136, M.iron);
  box(144, 16, 120, 196, 16, 121, M.wood);                       // running boards either side
  box(144, 16, 134, 196, 16, 135, M.wood);

  tubeX(162, 195, 20, 128, 5, M.boiler, 3);                      // boiler barrel
  for (const xr of [166, 178, 190]) tubeX(xr, xr, 20, 128, 5, M.iron); // hoops

  tubeY(170, 128, 25, 25, 2.6, M.trim);                          // brass steam dome
  tubeY(170, 128, 26, 26, 2.1, M.trim);
  tubeY(170, 128, 27, 27, 1.4, M.trim);
  put(170, 28, 128, M.trim);

  const stack = [[24, 2.6, M.coal], [25, 2.2, M.coal], [26, 2.0, M.coal], [27, 2.0, M.coal],
    [28, 1.7, M.coal], [29, 1.7, M.coal], [30, 1.7, M.coal], [31, 2.3, M.iron],
    [32, 1.9, M.coal], [33, 2.3, M.iron]];
  for (const [y, r, t] of stack) tubeY(188, 128, y, y, r, t, y === 33 ? 1.6 : 0);

  for (let y = 18; y <= 21; y++)                                 // headlamp, gold bezel
    for (let z = 126; z <= 129; z++)
      put(196, y, z, (y >= 19 && y <= 20 && z >= 127 && z <= 128) ? M.glow : M.trim);

  for (let x = 196; x <= 212; x++) {                             // cowcatcher: slatted wedge
    const top = Math.floor(12 - (x - 196) * 7 / 16);
    for (let y = 4; y <= top; y++)
      for (const z of [123, 125, 127, 129, 131]) put(x, y, z, M.iron);
  }
  for (let y = 4; y <= 5; y++) for (let z = 123; z <= 132; z++) put(212, y, z, M.trim); // gold nose

  for (let x = 144; x <= 161; x++)                               // cab shell
  for (let y = 16; y <= 30; y++)
  for (let z = 123; z <= 132; z++) {
    const shell = x === 144 || x === 161 || z === 123 || z === 132 || y === 16 || y === 30;
    if (!shell) continue;
    let t = M.cab;
    if ((z === 123 || z === 132) && y >= 21 && y <= 25 && (x - 144) % 4 !== 0) t = M.glass;
    if ((x === 144 || x === 161) && y >= 21 && y <= 25 && z >= 126 && z <= 129) t = M.glass;
    put(x, y, z, t);
  }
  box(143, 31, 122, 162, 31, 133, M.roof);                       // cab roof with overhang
}

function train() {
  coach(43, 76);
  line(77, 10, 128, 79, 10, 128, M.iron);
  coach(80, 113);
  line(114, 10, 128, 116, 10, 128, M.iron);
  tender();
  line(141, 10, 128, 143, 10, 128, M.iron);
  loco();
}

// Smoke plume drifting back from the stack, and a wisp of steam from the dome.
function smoke() {
  for (let i = 0; i < 14; i++)
    blob(188.5 - 2.4 * i + (rng() - 0.5) * 2, 35.5 + 1.6 * i + (rng() - 0.5),
         128.5 + (rng() - 0.5) * 2.5, 1.8 + 0.35 * i,
         i < 7 ? M.smoke : M.smoke2, 0.35, 0.9);
  blob(170.5, 30, 128.5, 1.6, M.smoke, 0.3, 0.9);
}

// ---- Run ---------------------------------------------------------------------
terrain();
flowers();
track();
station();
waterTower();
trees();
lamps();
train();
smoke();
